             backup_text =
               {x|# CROP PLOTTER EXTENSION TASK                     #
#                                                 #
# The crop plotter app lets you plant seeds on    #
# a grid. It already supports planting rows.      #
#                                                 #
# YOUR TASK: Add a PlantCol action that fills     #
# an entire column with the current seed.         #
#                                                 #
# You need to:                                    #
#   1. Add PlantCol(Col) to the Action type       #
#   2. Add a setCol helper function               #
#   3. Handle PlantCol in the update function     #
#                                                 #
# Look at how PlantRow is implemented for         #
# guidance - PlantCol is similar but vertical.    #
#                                                 #
# Tip: Use auto-probe to see how the grove        #
# changes after each action.                      #

type Plant = String in
type Grove = [[Plant]] in
type Row = Int in
type Col = Int in

type Model = (
grove = Grove,
currentSeed = Plant,
seedInventory = [Plant]
) in

type Action =
+ SelectSeed(Int)
+ PlantSeed(Row, Col)
+ Uproot(Row, Col)
+ ClearGrove
+ PlantRow(Row)
# TODO: Add PlantCol(Col) here #
in

let init: Model = (
grove = [
["", "", ""],
["", "", ""],
["", "", ""]
],
currentSeed = "🌱",
seedInventory = ["🌱", "🌿", "🍄", "☘️", "🌸"]
) in

let setCell: (Grove, Row, Col, Plant) -> Grove =
fun grove, row, col, plant ->
mapi(grove, fun (i, r) ->
if i == row
then mapi(r, fun (j, c) -> if j == col then plant else c)
else r)
in

let setRow: (Grove, Row, Plant) -> Grove =
fun grove, targetRow, plant ->
mapi(grove, fun (i, row) ->
if i == targetRow
then map(row, fun _ -> plant)
else row)
in

# TODO: Add setCol helper here #
# Hint: You need to modify each row, changing #
# only the cell at the target column.         #

let setAll: (Grove, Plant) -> Grove =
fun (grove, plant) ->
map(grove, fun row -> map(row, fun _ -> plant))
in

let updateGrove: (Model, Grove -> Grove) -> Model =
fun (m, f) -> (f(m.grove), m.currentSeed, m.seedInventory)
in

let update: (Model, Action) -> Model =
fun m, action ->
case action
| SelectSeed(idx) =>
(m.grove, nth(m.seedInventory, idx), m.seedInventory)
| PlantSeed(row, col) =>
updateGrove(m, fun g -> setCell(g, row, col, m.currentSeed))
| Uproot(row, col) =>
updateGrove(m, fun g -> setCell(g, row, col, ""))
| ClearGrove =>
updateGrove(m, fun g -> setAll(g, ""))
| PlantRow(row) =>
updateGrove(m, fun g -> setRow(g, row, m.currentSeed))
# TODO: Add PlantCol case here #
end
in

let do: (Model, [Action]) -> Model =
fun (init: Model, actions: [Action]) ->
fold_left(actions, fun (m, a) -> update(m, a), init)
in

# Existing tests #
test
let m = update(init, PlantRow(1)) in
m.grove == [["", "", ""], ["🌱", "🌱", "🌱"], ["", "", ""]]
end;

# New tests for PlantCol #
test
let m = update(init, PlantCol(0)) in
m.grove == [["🌱", "", ""], ["🌱", "", ""], ["🌱", "", ""]]
end;

test
let m = update(init, PlantCol(2)) in
m.grove == [["", "", "🌱"], ["", "", "🌱"], ["", "", "🌱"]]
end;

test
let m = do(init, [PlantRow(0), PlantCol(1)]) in
m.grove == [["🌱", "🌱", "🌱"], ["", "🌱", ""], ["", "🌱", ""]]
end;

test
let m = do(init, [SelectSeed(2), PlantCol(1)]) in
m.grove == [["", "🍄", ""], ["", "🍄", ""], ["", "🍄", ""]]
&& m.currentSeed == "🍄"
end|x};
